def max_ones_row_brute(m: list[list[int]]) -> int:
    best_row, best = -1, -1
    for i, row in enumerate(m):
        c = sum(row)
        if c > best:
            best, best_row = c, i
    return best_row

def max_ones_row(mat: list[list[int]]) -> int:
    def first_one(row: list[int]) -> int:
        lo, hi, ans = 0, len(row) - 1, len(row)
        while lo <= hi:
            mid = lo + (hi - lo) // 2
            if row[mid] >= 1:
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

    best_row, best = -1, 0
    for i, row in enumerate(mat):
        cnt = len(row) - first_one(row)
        if cnt > best:
            best, best_row = cnt, i
    return best_row

def max_ones_row_staircase(mat: list[list[int]]) -> int:
    n, m = len(mat), len(mat[0])
    j = m - 1
    best_row = -1
    for i in range(n):
        while j >= 0 and mat[i][j] == 1:
            j -= 1
            best_row = i
    return best_row
